datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider        = "prisma-client-js"
  previewFeatures = ["fullTextSearchPostgres"]
}

model Product {
  id          Int      @id @default(autoincrement())
  name        String
  description String
  category    String
  brand       String
  price       Float
  rating      Float
  inStock     Boolean
  createdAt   DateTime @default(now())
}

import { PrismaClient } from '@prisma/client'

export async function seed(prisma: PrismaClient) {
  const count = await prisma.product.count();
  if (count > 0) {
    console.log('Database already seeded with products.');
    return;
  }

  const products = [
    {
      name: 'SuperFast Wireless Charger',
      description: 'A high-speed wireless charging pad for all Qi-enabled smartphones and devices.',
      category: 'Electronics',
      brand: 'VoltCharge',
      price: 29.99,
      rating: 4.5,
      inStock: true,
    },
    {
      name: 'UltraQuiet Blending Machine',
      description: 'Professional grade blender with sound dampening shield and 1200W motor.',
      category: 'Home & Kitchen',
      brand: 'NutriBlend',
      price: 89.99,
      rating: 4.8,
      inStock: true,
    },
    {
      name: 'Ergonomic Office Desk Chair',
      description: 'High-back mesh chair with adjustable lumbar support and 3D armrests.',
      category: 'Furniture',
      brand: 'ErgoComfort',
      price: 149.99,
      rating: 4.2,
      inStock: false,
    },
    {
      name: 'VoltCharge Portable Power Bank',
      description: 'Compact 20000mAh external battery pack with dual USB-C fast charging.',
      category: 'Electronics',
      brand: 'VoltCharge',
      price: 39.99,
      rating: 4.6,
      inStock: true,
    },
    {
      name: 'NutriBlend Compact Juicer',
      description: 'Centrifugal juicing machine with wide feed chute, easy to clean.',
      category: 'Home & Kitchen',
      brand: 'NutriBlend',
      price: 49.99,
      rating: 4.0,
      inStock: true,
    },
    {
      name: 'Leather Executive Swivel Chair',
      description: 'Premium genuine leather office chair with padded armrests and tilt lock.',
      category: 'Furniture',
      brand: 'ErgoComfort',
      price: 249.99,
      rating: 4.7,
      inStock: true,
    },
  ];

  for (const product of products) {
    await prisma.product.create({
      data: product,
    });
  }

  console.log('Successfully seeded 6 products.');
}

import { Product } from '@prisma/client';

export type GetProductsInput = {
  search?: string;
  category?: string;
  brand?: string;
  minPrice?: number;
  maxPrice?: number;
  inStock?: boolean;
  sortBy?: 'price_asc' | 'price_desc' | 'rating_desc' | 'createdAt_desc';
  limit?: number;
  cursor?: number;
};

export type GetProductsOutput = {
  products: Product[];
  nextCursor: number | null;
  facets: {
    categories: { name: string; count: number }[];
    brands: { name: string; count: number }[];
  };
};

export const getProductsWithFilters = async (
  args: GetProductsInput,
  context: any
): Promise<GetProductsOutput> => {
  const {
    search,
    category,
    brand,
    minPrice,
    maxPrice,
    inStock,
    sortBy,
    limit = 10,
    cursor,
  } = args;

  const baseFilter: any = {};
  if (category) {
    baseFilter.category = category;
  }
  if (brand) {
    baseFilter.brand = brand;
  }
  if (minPrice !== undefined) {
    baseFilter.price = { ...baseFilter.price, gte: minPrice };
  }
  if (maxPrice !== undefined) {
    baseFilter.price = { ...baseFilter.price, lte: maxPrice };
  }
  if (inStock === true) {
    baseFilter.inStock = true;
  }

  const searchQuery = search?.trim();

  // Define orderBy
  let orderByClause: any = [{ id: 'asc' }];
  if (sortBy === 'price_asc') {
    orderByClause = [{ price: 'asc' }, { id: 'asc' }];
  } else if (sortBy === 'price_desc') {
    orderByClause = [{ price: 'desc' }, { id: 'asc' }];
  } else if (sortBy === 'rating_desc') {
    orderByClause = [{ rating: 'desc' }, { id: 'asc' }];
  } else if (sortBy === 'createdAt_desc') {
    orderByClause = [{ createdAt: 'desc' }, { id: 'asc' }];
  }

  // We will try running with full-text search. If it fails, fallback to contains.
  const runQuery = async (useFullText: boolean) => {
    let searchFilter: any = {};
    if (searchQuery) {
      if (useFullText) {
        // Format for postgres full-text search
        const cleanSearch = searchQuery
          .replace(/[^a-zA-Z0-9\s]/g, '')
          .split(/\s+/)
          .filter(Boolean)
          .join(' & ');
        if (cleanSearch) {
          searchFilter = {
            OR: [
              { name: { search: cleanSearch } },
              { description: { search: cleanSearch } },
            ],
          };
        }
      } else {
        // Fallback to contains
        searchFilter = {
          OR: [
            { name: { contains: searchQuery, mode: 'insensitive' } },
            { description: { contains: searchQuery, mode: 'insensitive' } },
          ],
        };
      }
    }

    const whereClause = {
      AND: [baseFilter, searchFilter],
    };

    const limitWithExtra = limit + 1;
    const products = await context.entities.Product.findMany({
      where: whereClause,
      take: limitWithExtra,
      cursor: cursor ? { id: cursor } : undefined,
      skip: cursor ? 1 : 0,
      orderBy: orderByClause,
    });

    let nextCursor: number | null = null;
    const resultProducts = [...products];
    if (resultProducts.length > limit) {
      resultProducts.pop();
      nextCursor = resultProducts[resultProducts.length - 1].id;
    }

    // Dynamic Facets
    const categoryGroups = await context.entities.Product.groupBy({
      by: ['category'],
      where: whereClause,
      _count: {
        category: true,
      },
    });

    const brandGroups = await context.entities.Product.groupBy({
      by: ['brand'],
      where: whereClause,
      _count: {
        brand: true,
      },
    });

    const categories = categoryGroups.map((g: any) => ({
      name: g.category,
      count: g._count.category,
    }));

    const brands = brandGroups.map((g: any) => ({
      name: g.brand,
      count: g._count.brand,
    }));

    return {
      products: resultProducts,
      nextCursor,
      facets: {
        categories,
        brands,
      },
    };
  };

  try {
    return await runQuery(true);
  } catch (error) {
    console.error('Full-text search failed, falling back to contains-based search:', error);
    return await runQuery(false);
  }
};

import { app, page, route, query } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { getProductsWithFilters } from "./src/queries" with { type: "ref" };
import { seed } from "./src/seeds" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  db: {
    seeds: [seed],
  },
  spec: [
    route("RootRoute", "/", page(MainPage)),
    query(getProductsWithFilters, { entities: ["Product"] }),
  ],
});

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider        = "prisma-client-js"
  previewFeatures = ["fullTextSearch"]
}

model Product {
  id          Int      @id @default(autoincrement())
  name        String
  description String
  category    String
  brand       String
  price       Float
  rating      Float
  inStock     Boolean
  createdAt   DateTime @default(now())
}
